package main
import("os";"fmt";"bytes";"encoding/json";"crypto/sha256";"github.com/minz/minzc/pkg/z80asm")
func main(){s,e:=os.ReadFile(os.Args[1]);if e!=nil{panic(e)};a,e:=z80asm.NewAssembler().AssembleString(string(s));if e!=nil||len(a.Errors)>0{panic(fmt.Sprint(e,a.Errors))};saved,e:=os.ReadFile(os.Args[2]);if e!=nil{panic(e)};if !bytes.Equal(saved,a.Binary){panic("mza binary differs")};seen:=map[int]bool{};for _,l:=range a.Listing{for i,v:=range l.Bytes{addr:=l.Address+i;if addr<a.Origin||addr-a.Origin>=len(a.Binary)||a.Binary[addr-a.Origin]!=v||seen[addr]{panic(fmt.Sprint("bad listing byte",addr))};seen[addr]=true}};if len(seen)!=len(a.Binary)||len(a.Binary)!=a.Symbols["__cpm_smoke_image_end"]-a.Origin||a.Symbols["__cpm_smoke_code_end"]>=0x6000{panic("incomplete flat image")};b,_:=json.MarshalIndent(map[string]any{"complete_listing_bytes":len(seen),"image_bytes":len(a.Binary),"origin":a.Origin,"sha256":fmt.Sprintf("%x",sha256.Sum256(a.Binary)),"all_bytes_contiguous_and_equal":true,"mza_binary_equal":true,"execution_performed":false},"","  ");fmt.Println(string(b))}
